/* 5x7 bitmap font (generated by tools/font.py). */
'use strict';
const Font = (() => {
  const CHARS = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~ÄÖÜäöü©";
  const DATA = '';
  const glyphs = {};
  for (let i = 0; i < CHARS.length; i++) {
    const rows = [];
    for (let r = 0; r < 7; r++) rows.push(parseInt(DATA.substr((i * 7 + r) * 2, 2), 16));
    glyphs[CHARS[i]] = rows;
  }
  return { glyphs, W: 5, H: 7 };
})();
